CREATE VIRTUAL TABLE ft USING fts3(a, b); WITH RECURSIVE n(ii) AS (VALUES(1) UNION ALL SELECT ii+1 FROM n WHERE ii<1023) INSERT INTO ft(a,b) SELECT rtrim(CASE WHEN (ii & 1)<>0 THEN 'one ' ELSE '' END || CASE WHEN (ii & 2)<>0 THEN 'two ' ELSE '' END || CASE WHEN (ii & 4)<>0 THEN 'three ' ELSE '' END || CASE WHEN (ii & 8)<>0 THEN 'four ' ELSE '' END || CASE WHEN (ii & 16)<>0 THEN 'five ' ELSE '' END || CASE WHEN (ii & 32)<>0 THEN 'six ' ELSE '' END || CASE WHEN (ii & 64)<>0 THEN 'seven ' ELSE '' END || CASE WHEN (ii & 128)<>0 THEN 'eight ' ELSE '' END || CASE WHEN (ii & 256)<>0 THEN 'nine ' ELSE '' END || CASE WHEN (ii & 512)<>0 THEN 'ten ' ELSE '' END), rtrim(CASE WHEN (ii & 1)<>0 THEN 'neung ' ELSE '' END || CASE WHEN (ii & 2)<>0 THEN 'song ' ELSE '' END || CASE WHEN (ii & 4)<>0 THEN 'sahm ' ELSE '' END || CASE WHEN (ii & 8)<>0 THEN 'see ' ELSE '' END || CASE WHEN (ii & 16)<>0 THEN 'hah ' ELSE '' END || CASE WHEN (ii & 32)<>0 THEN 'hok ' ELSE '' END || CASE WHEN (ii & 64)<>0 THEN 'jet ' ELSE '' END || CASE WHEN (ii & 128)<>0 THEN 'bairt ' ELSE '' END || CASE WHEN (ii & 256)<>0 THEN 'gow ' ELSE '' END || CASE WHEN (ii & 512)<>0 THEN 'sip ' ELSE '' END) FROM n ORDER BY ii;